sys_data_source.data_loader:
(function loadData(import_set_table) {

	var apiKey = gs.getProperty('x_854636_b_board.apac1_api_token');
	var r = new sn_ws.RESTMessageV2('x_854636_b_board.Brainboard - apac1', 'ListArchitectureTemplates');
	r.setStringParameterNoEscape('token', apiKey);
	var response = r.execute();
	var responseBody = response.getBody();
	var httpStatus = response.getStatusCode();
	var resp = global.JSON.parse(responseBody);

	// Iterate through the array elements
	for (var i = 0; i < resp.length; i++) {
		resp[i].api_type = "apac1";
		import_set_table.insert(resp[i]);
	}

})(import_set_table);

